content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #cbd5e1;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 800px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  margin-bottom: 24px;
}

.form-group {
  margin-bottom: 16px;
}

.label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--text-main);
}

.input, .select {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background-color: #ffffff;
  color: var(--text-main);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus, .select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
  margin-top: 16px;
}

.result-card {
  background-color: #f1f5f9;
  border-radius: 8px;
  padding: 16px;
  border: 1px solid #e2e8f0;
}

.unit-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.unit-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary-color);
  word-break: break-all;
}

.conversion-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 16px;
  text-align: left;
}

.th, .td {
  padding: 12px 16px;
  border-bottom: 1px solid #e2e8f0;
}

.th {
  font-weight: 600;
  color: var(--text-muted);
  background-color: #f8fafc;
}

.td {
  color: var(--text-main);
}

.btn-reset {
  background-color: #e2e8f0;
  color: var(--text-main);
  border: none;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn-reset:hover {
  background-color: #cbd5e1;
}

@media (max-width: 600px) {
  body {
    padding: 10px;
  }
  .app-container {
    padding: 12px;
  }
  .card {
    padding: 16px;
  }
}

export type UnitType = 'mm' | 'cm' | 'm' | 'km' | 'inch' | 'feet';

export interface ConversionResult {
  unit: UnitType;
  label: string;
  value: string;
}

import { useState, ChangeEvent } from 'react';
import { UnitType } from '../types';
import '../index.css';

interface ConverterFormProps {
  value: string;
  onChangeValue: (val: string) => void;
  unit: UnitType;
  onChangeUnit: (unit: UnitType) => void;
}

export default function ConverterForm({
  value,
  onChangeValue,
  unit,
  onChangeUnit,
}: ConverterFormProps) {
  const units: { type: UnitType; label: string }[] = [
    { type: 'mm', label: 'ミリメートル (mm)' },
    { type: 'cm', label: 'センチメートル (cm)' },
    { type: 'm', label: 'メートル (m)' },
    { type: 'km', label: 'キロメートル (km)' },
    { type: 'inch', label: 'インチ (in)' },
    { type: 'feet', label: 'フィート (ft)' },
  ];

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeValue(e.target.value);
  };

  const handleSelectChange = (e: ChangeEvent<HTMLSelectElement>) => {
    onChangeUnit(e.target.value as UnitType);
  };

  return (
    <div className="card">
      <div className="form-group">
        <label className="label" htmlFor="length-value">
          変換する長さ
        </label>
        <input
          id="length-value"
          type="number"
          className="input"
          value={value}
          onChange={handleInputChange}
          placeholder="数値りを入力してください"
        />
      </div>

      <div className="form-group">
        <label className="label" htmlFor="length-unit">
          基準の単位
        </label>
        <select
          id="length-unit"
          className="select"
          value={unit}
          onChange={handleSelectChange}
        >
          {units.map((u) => (
            <option key={u.type} value={u.type}>
              {u.label}
            </option>
          ))}
        </select>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { UnitType, ConversionResult } from './types';
import ConverterForm from './components/ConverterForm';
import ConversionTable from './components/ConversionTable';
import './index.css';

export default function App() {
  const [value, setValue] = useState<string>('1');
  const [unit, setUnit] = useState<UnitType>('m');

  // すべてミリメートル(mm)を基準として内部計算する
  const toMillimeters = (val: number, currentUnit: UnitType): number => {
    switch (currentUnit) {
      case 'mm':
        return val;
      case 'cm':
        return val * 10;
      case 'm':
        return val * 1000;
      case 'km':
        return val * 1000000;
      case 'inch':
        return val * 25.4;
      case 'feet':
        return val * 304.8;
      default:
        return val;
    }
  };

  const fromMillimeters = (mm: number, targetUnit: UnitType): number => {
    switch (targetUnit) {
      case 'mm':
        return mm;
      case 'cm':
        return mm / 10;
      case 'm':
        return mm / 1000;
      case 'km':
        return mm / 1000000;
      case 'inch':
        return mm / 25.4;
      case 'feet':
        return mm / 304.8;
      default:
        return mm;
    }
  };

  const formatValue = (num: number): string => {
    if (isNaN(num)) return '0';
    if (num === 0) return '0';
    // 非常に小さい、あるいは大きい数値の場合は指数表記や小数点調整
    if (Math.abs(num) < 0.000001 || Math.abs(num) > 1e12) {
      return num.toExponential(4);
    }
    // 小数点以下を適切に丸める（最大6桁）
    return parseFloat(num.toFixed(6)).toString();
  };

  const numValue = parseFloat(value) || 0;
  const mmBase = toMillimeters(numValue, unit);

  const unitLabels: Record<UnitType, string> = {
    mm: 'ミリメートル',
    cm: 'センチメートル',
    m: 'メートル',
    km: 'キロメートル',
    inch: 'インチ',
    feet: 'フィート',
  };

  const units: UnitType[] = ['mm', 'cm', 'm', 'km', 'inch', 'feet'];

  const results: ConversionResult[] = units.map((u) => {
    const converted = fromMillimeters(mmBase, u);
    return {
      unit: u,
      label: unitLabels[u],
      value: formatValue(converted),
    };
  });

  const handleReset = () => {
    setValue('1');
    setUnit('m');
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">長さの単位変換</h1>
        <button className="btn-reset" onClick={handleReset}>
          リセット
        </button>
      </header>

      <ConverterForm
        value={value}
        onChangeValue={setValue}
        unit={unit}
        onChangeUnit={setUnit}
      />

      <ConversionTable results={results} />
    </div>
  );
}
